const fs = require('fs');
const path = require('path');
const { loadConfig } = require('../config');
const { pagesDir, flowsDir } = require('../catalog');
const { mergeSnapshot, pageName } = require('../pages');
const { regionsFor } = require('../regions');

const NAME_RE = /^[\w-]+$/;
// ids generated by UI libraries on each render (radix-:r1:, :r5:, headlessui-..., mui-...) are not stable
const AUTO_ID = /:|^(radix|headlessui|mui|react-aria|rc-|downshift)/i;

// Ids with uuids or long digit runs are per-record (e.g. orders-order-card-<uuid>); store them as a pattern.
const normalize = (s) => (s || '')
    .replace(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/gi, '*')
    .replace(/\d{4,}/g, '*');

// People's names never go into the knowledge files. `identity` (a pack's, the config's, `apps.<app>.identity`: CSS
// selectors of the elements that show who is signed in, e.g. '#topbar-account-name') tells the probe where to read the
// name from; its words are then replaced by `*` everywhere a snapshot records text (headings, button text, labels).
const identityFor = (config, app) => [
    ...(config.packs || []).flatMap((p) => p.identity || []),
    ...(config.identity || []),
    ...((app && config.apps[app] && config.apps[app].identity) || []),
];
const knownNames = new Set();   // lower-cased words of the names seen so far in this probe run

// `text` with every known name word (whole words, any letters) replaced by `*`.
function redact(text, names = knownNames) {
    if (!text) return text;
    let out = text;
    for (const word of names) {
        const escaped = word.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        out = out.replace(new RegExp(`(?<![\\p{L}\\p{N}])${escaped}(?![\\p{L}\\p{N}])`, 'giu'), '*');
    }
    return out;
}

// Repeated clickable elements whose ids differ only in the last part (orders-list-testorder518, orders-list-e2e123...):
// one entry per family, so `gen` can target a record by its number ("I click {orderNumber}"). Only the shared prefix
// is stored, never the record parts. Calendar days (an id ending in a full date) are not families.
function cardFamilies(elements) {
    const groups = new Map();
    for (const e of elements) {
        if (!e.id || !(e.tag === 'a' || e.tag === 'button' || e.clickable)) continue;
        if (/\d{4}-\d{2}-\d{2}$/.test(e.id)) continue;   // calendar days are not records
        const prefix = e.id.replace(/[^-]+$/, '');
        if (!prefix || prefix === e.id) continue;
        const g = groups.get(prefix) || { prefix, tag: e.tag, count: 0 };
        g.count += 1;
        groups.set(prefix, g);
    }
    return [...groups.values()].filter((g) => g.count >= 2);
}

// What this probe run has done, written to <knowledgeDir>/flows/<steps file>.json after every change so a run that
// fails part-way keeps what it reached. The pages themselves are shared by all steps files (see pages.js); this is
// only the order they were visited in and the names the steps resolved, which lets `gen` tell apart elements that
// share a label ("Email Address" on two wizard steps).
// A steps file with variants or an examples table records one flow per test: each test starts with startFlow(name).
let current = null;
const flow = () => (current || process.env.PROBE_FLOW || 'probe').replace(/[^\w-]+/g, '-');
const visits = [];
const names = [];
let lastIds = null;     // visible ids of the last snapshot, to notice when the page has changed

// Starts recording a new flow (one test of a probe): the visits and names that follow go to <knowledgeDir>/flows/<name>.json.
function startFlow(name) {
    current = name;
    visits.length = 0;
    names.length = 0;
    lastIds = null;
}

function writeFlow() {
    const dir = flowsDir(loadConfig());
    fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(path.join(dir, `${flow()}.json`), JSON.stringify({ flow: flow(), visits, names }, null, 2) + '\n');
}

const visibleIds = (page) => page.evaluate(() => [...document.querySelectorAll('[id]')]
    .filter((el) => el.getClientRects().length > 0 && el.id !== 'root').map((el) => el.id));

// Records the interactive elements of the current page into its shared record, <knowledgeDir>/pages/<app>/<slug>.json
// (created, or updated in place), and logs the visit in this steps file's flow. `name` only labels the console line.
// Does nothing unless PROBE=1 (set by `npm run probe`), so snapshot steps are harmless in normal runs.
// Never records input values or dropdown options: the data on these pages is real-looking and may be personal.
async function snapshotPage(page, name, app) {
    if (!process.env.PROBE) return;
    if (!NAME_RE.test(name)) throw new Error(`snapshot name must match ${NAME_RE}: ${name}`);
    await page.waitForLoadState('load');

    const regions = Object.entries(regionsFor(loadConfig(), app));
    const identity = identityFor(loadConfig(), app);
    const data = await page.evaluate(({ regions, identity }) => {
        const isIdentity = (el) => identity.some((sel) => el.matches(sel) || el.querySelector(sel));
        const names = [];
        for (const sel of identity) {
            for (const el of document.querySelectorAll(sel)) {
                for (const t of [el.innerText, el.getAttribute('title'), el.getAttribute('aria-label')]) {
                    names.push(...(t || '').split(/[\s,]+/).filter((w) => w.length >= 2));
                }
            }
        }
        // the first region (in precedence order) the element sits in; anywhere else is the main area
        const regionOf = (el) => {
            for (const [name, selector] of regions) if (el.closest(selector)) return name;
            return 'main';
        };
        const labelOf = (el) => {
            const aria = el.getAttribute('aria-label');
            if (aria) return aria.trim();
            if (el.labels && el.labels[0]) return el.labels[0].innerText.trim();
            const scope = el.closest('div');
            const near = scope && scope.querySelector('label');
            return (near && near.innerText.trim()) || el.getAttribute('placeholder') || undefined;
        };
        const seen = new Set();
        const elements = [];
        for (const el of document.querySelectorAll('[id], input, textarea, select, button, a[href]')) {
            if (!(el instanceof HTMLElement) || el.id === 'root') continue;
            const key = el.id || `${el.tagName}:${el.getAttribute('name')}:${el.getAttribute('type')}`;
            if (seen.has(key)) continue;
            seen.add(key);
            const tag = el.tagName.toLowerCase();
            const role = el.getAttribute('role') || undefined;
            const isField = ['input', 'textarea', 'select'].includes(tag) || role === 'combobox';
            // cards, suggestion items and tabs built from divs: clickable if they say so (role) or look it (pointer
            // cursor that their parent does not have, so a card counts but not every child inside it)
            const pointer = (node) => node && getComputedStyle(node).cursor === 'pointer';
            const clickable = !['button', 'a', 'input', 'select', 'textarea', 'label'].includes(tag) && el.id
                && (['option', 'tab', 'menuitem', 'button', 'link'].includes(role) || el.onclick || (pointer(el) && !pointer(el.parentElement)));
            const region = regionOf(el);
            elements.push({
                id: el.id || undefined,
                region,
                tag,
                type: el.getAttribute('type') || undefined,
                name: el.getAttribute('name') || undefined,
                label: isField && !isIdentity(el) ? labelOf(el) : undefined,
                // visible text only for buttons and sidebar navigation (other links show user names and other data),
                // and only a single line: a multi-line button is an avatar/name/role block, not a label
                // toast heading/message text is kept too (longer limit): it is what a steps file asserts on, and it is
                // system wording, not user data. It still goes through redact() below.
                text: (tag === 'button' || (region === 'sidebar' && /^(side)?nav-/.test(el.id))
                    || (region === 'toast' && /-(heading|message)$/.test(el.id))) && !isIdentity(el)
                    && !/\n/.test(el.innerText.trim())
                    ? el.innerText.trim().slice(0, region === 'toast' ? 120 : 40) || undefined : undefined,
                role,
                clickable: clickable ? true : undefined,
                readonly: el.readOnly || undefined,
                disabled: el.disabled || undefined,
                visible: el.getClientRects().length > 0,
            });
        }
        const headings = [...document.querySelectorAll('h1, h2, h3')].map((h) => h.innerText.trim()).filter(Boolean);
        return { path: location.pathname, headings, elements, names };
    }, { regions, identity });

    for (const word of data.names) knownNames.add(word.toLowerCase());
    data.headings = data.headings.map((h) => redact(h));
    data.elements = data.elements.map((e) => ({ ...e, text: redact(e.text), label: redact(e.label) }));

    data.elements = data.elements.map((e) => (e.id && AUTO_ID.test(e.id) ? { ...e, id: undefined } : e))
        .filter((e) => e.id || e.tag !== 'div');
    const snap = {
        app: app || undefined,
        path: normalize(data.path),
        headings: data.headings,
        cards: cardFamilies(data.elements),
        elements: data.elements.map((e) => ({ ...e, id: e.id && normalize(e.id) })),
    };
    const dir = pagesDir(loadConfig());
    const file = path.join(dir, `${pageName(snap.app, snap.path)}.json`);
    const existing = fs.existsSync(file) ? JSON.parse(fs.readFileSync(file, 'utf8')) : null;
    const { page: merged, state, isNewPage, isNewState, changed } = mergeSnapshot(existing, snap);
    if (changed || isNewPage) {
        fs.mkdirSync(path.dirname(file), { recursive: true });
        fs.writeFileSync(file, JSON.stringify(merged, null, 2) + '\n');
    }
    const last = visits[visits.length - 1];
    if (!last || last.page !== merged.name || last.state !== state.id) visits.push({ page: merged.name, state: state.id });
    writeFlow();
    lastIds = new Set(await visibleIds(page));
    console.log(`Snapshot ${merged.name} ${state.id}: ${isNewPage ? 'new page' : isNewState ? 'new state' : changed ? 'updated' : 'unchanged'} (${merged.elements.length} elements, ${name})`);
}

// Probe runs call this before every action: once the target is there, if the page shows ids the last snapshot did
// not have (a new page, wizard step or modal), the page is recorded or updated in its shared record. No-op outside
// probes.
async function autoSnapshot(page, app, target) {
    if (!process.env.PROBE) return;
    if (target) {
        const loc = typeof target === 'string' ? page.locator(target).first() : target;
        const isFile = (await loc.getAttribute('type').catch(() => null)) === 'file';
        await loc.waitFor({ state: isFile ? 'attached' : 'visible' });
    }
    // the last page of a flow (no target): let a redirect after the final click land before recording it
    else await page.waitForLoadState('networkidle', { timeout: 10000 }).catch(() => {});
    const ids = await visibleIds(page);
    if (lastIds && ids.every((id) => lastIds.has(id))) return;
    await snapshotPage(page, `${flow()}-${visits.length + 1}`, app);
}

// Records in this steps file's flow which element a probe step's name ("Create Order", a supplier's name) resolved
// to, so `gen` resolves the same name to the same id, even for elements with no label or recorded text.
function noteName(kind, name, id) {
    const visit = visits[visits.length - 1];
    if (!process.env.PROBE || !visit || !id || !name) return;
    const at = names.findIndex((n) => n.kind === kind && n.name === name && n.page === visit.page && n.state === visit.state);
    if (at >= 0) names.splice(at, 1);
    names.push({ ...visit, kind, name, id: normalize(id) });
    writeFlow();
}

module.exports = { snapshotPage, autoSnapshot, startFlow, noteName, visibleIds, redact, cardFamilies };
